static int  g_quitting;

/* Is `t` (minutes since midnight) inside the DND window? Windows may wrap past
 * midnight, which is why this is not a plain range test. */
/* Minutes east of UTC, right now — oc_utc_offset_min (shared/oc_port.h). This
 * file used to carry its own copy; the app-core needs the same number to refresh
 * the stored offset on connect (ARCH-103), so it moved to the header they share
 * rather than becoming a second implementation to keep in step. */
#define local_utc_offset_min() oc_utc_offset_min()

/* Am I quiet right now? The rule lives in shared/notify.c (ARCH-103), because
 * the daemon applies exactly the same one when it decides whether to notify —
 * and this file used to carry TWO divergent copies of the simpler version it
 * replaced, one for the tray and one for the header. */
static int dnd_active(const oc_model *m) {
    if (!m || m->dnd_mode == OC_DND_OFF) return 0;
    time_t now = time(NULL); struct tm tv;
    if (!oc_localtime_r(&now, &tv)) return 0;
    int local_min = tv.tm_hour * 60 + tv.tm_min, weekday = tv.tm_wday;
    int present = 0, enabled = 0, ds = 0, de = 0;
    for (uint8_t i = 0; i < m->n_sched_days; i++)
        if (m->sched_days[i].weekday == weekday) {
            present = 1; enabled = m->sched_days[i].enabled;
            ds = m->sched_days[i].start_min; de = m->sched_days[i].end_min;
            break;
        }
    return oc_notify_quiet(m->dnd_mode, m->allow_start_min, m->allow_end_min,
                           present, enabled, ds, de, local_min, weekday);
}

static void tray_init(HWND hwnd) {
    memset(&g_tray, 0, sizeof g_tray);
    g_tray.cbSize = sizeof g_tray;
    g_tray.hWnd = hwnd;
    g_tray.uID = TRAY_UID;
    /* NIF_MESSAGE is what makes it a control rather than a mailbox: without a
     * callback the icon could raise balloons and take no clicks, so there was no
     * way back to a hidden window and no way to quit from it. */
    g_tray.uFlags = NIF_ICON | NIF_TIP | NIF_MESSAGE;
    g_tray.uCallbackMessage = WM_APP_TRAY;
    g_tray.hIcon = LoadIconW(GetModuleHandleW(NULL), MAKEINTRESOURCEW(IDI_APPICON));
    if (!g_tray.hIcon) g_tray.hIcon = LoadIconW(NULL, IDI_APPLICATION);
    lstrcpynW(g_tray.szTip, L"OpenChime", 128);
    g_tray_live = Shell_NotifyIconW(NIM_ADD, &g_tray) ? 1 : 0;
    /* Version 4 behaviour, and it is not optional: without NIM_SETVERSION the
     * shell never sends NIN_BALLOONUSERCLICK at all, so a balloon stays a
     * poster however carefully its click is handled. */
    if (g_tray_live) { g_tray.uVersion = NOTIFYICON_VERSION_4;
                       Shell_NotifyIconW(NIM_SETVERSION, &g_tray); }
}

static void tray_done(void) {
    if (g_tray_live) { Shell_NotifyIconW(NIM_DELETE, &g_tray); g_tray_live = 0; }
}

static int g_toasts_raised;      /* observable by the harness; see test_dump */

/* ---- notification sounds (REQ-138) ---------------------------------------
 * The client was silent. A notification you have to be looking at the screen to
 * receive is half a notification, and the audible half is the one that works
 * when the window is behind something.
 *
 * PER EVENT, not one sound for everything, because REQ-138 argues the point
 * directly: a cue is only useful if it distinguishes, and one sound for
 * everything trains you to ignore it. An empty path means "the system default
 * for this event", which on the OS backend means letting Windows play the
 * toast's own sound rather than layering a second one over it. */
/* THE SYSTEM'S OWN SOUNDS, named rather than shipped. Windows already has a set
 * of notification sounds, the user has already chosen how they should behave,
 * and both surfaces can ask for one BY NAME -- the toast XML through
 * `ms-winsoundevent:`, PlaySound through SND_ALIAS. So there is nothing to
 * bundle, nothing to install, and a person who has quietened or changed their
 * notification sound is followed rather than talked over.
 *
 * The alternative was shipping .wav files, which would have meant carrying
 * audio in the installer to reproduce, worse, a sound the machine already had.
 *
 * Per event, because REQ-138 argues the point directly: a cue is only useful if
 * it distinguishes, and one sound for everything trains you to ignore it. The
 * names are Windows' own event names, so "a message" and "a mention" differ the
 * way the OS already differentiates them. */
enum { OCSND_MESSAGE = 0, OCSND_PRIORITY, OCSND_DM, OCSND_CALL, OCSND_COUNT };
enum { SNDV_DEFAULT = 0, SNDV_IM, SNDV_MAIL, SNDV_REMINDER, SNDV_SILENT, SNDV_COUNT };
static const struct { const char *label, *winsound, *alias; } SNDV[SNDV_COUNT] = {
    /* label        toast XML (ms-winsoundevent:)            PlaySound SND_ALIAS */
    { "Default",   "ms-winsoundevent:Notification.Default",  "Notification.Default"  },
    { "Message",   "ms-winsoundevent:Notification.IM",       "Notification.IM"       },
    { "Mail",      "ms-winsoundevent:Notification.Mail",     "Notification.Mail"     },
    { "Reminder",  "ms-winsoundevent:Notification.Reminder", "Notification.Reminder" },
    { "Silent",    "",                                       NULL                    },
};
static int  g_snd_choice[OCSND_COUNT] = { SNDV_IM, SNDV_REMINDER, SNDV_MAIL, SNDV_DEFAULT };
static int  g_snd_muted;           /* one switch, leaving the choices intact */

/* Which system sound this event asks for. Returns an index into SNDV; muting
 * answers SILENT without disturbing what each event is set to. */
static int sound_choice_for(int is_priority, int is_dm) {
    if (g_snd_muted) return SNDV_SILENT;
    int which = is_priority ? OCSND_PRIORITY : is_dm ? OCSND_DM : OCSND_MESSAGE;
    return g_snd_choice[which];
}

/* Play one ourselves. Only the client's OWN notification window needs this: the
 * OS toast is told which sound to use and Windows plays it, which is both one
 * fewer thing to get wrong and the only way the sound obeys Focus Assist. */
static void sound_play(int v) {
    if (v < 0 || v >= SNDV_COUNT || !SNDV[v].alias) return;
    WCHAR w[96];
    MultiByteToWideChar(CP_UTF8, 0, SNDV[v].alias, -1, w, 96);
    /* ALIAS, not a filename: this is a registered system event, so a user who
     * has silenced notification sounds is silenced here too. ASYNC so a
     * notification never blocks the tick; NODEFAULT so an unknown alias is
     * silence rather than the generic ding, which would be a worse lie. */
    PlaySoundW(w, NULL, SND_ASYNC | SND_ALIAS | SND_NODEFAULT);
}

/* The tray balloon. No longer the mechanism -- it is the middle of the chain
 * below -- but kept, because it is the one surface that needs no identity. */
static int notify_balloon(const char *title, const char *body) {
    if (!g_tray_live) return 0;
    g_tray.uFlags = NIF_INFO;
    g_tray.dwInfoFlags = NIIF_NONE;
    to_w(title, g_tray.szInfoTitle, 64);
    to_w(body,  g_tray.szInfo, 256);
    return Shell_NotifyIconW(NIM_MODIFY, &g_tray) ? 1 : 0;
}

static void own_toast_show(const char *title, const char *body,
                           uint64_t ws_slot, uint64_t channel_id);   /* fwd */

static void toast_action_perform(char *payload);   /* fwd — defined with the
                                                    notification window, which is
                                                    where the model is in scope */

/* What a toast's BUTTON did, arriving on the COM activator's thread.
 *
 * It does not act. The model, the client and every rect belong to the UI
 * thread, so this hands the string over as a message and returns -- the same
 * discipline the net thread already follows. Acting here would be a data race
 * with the frame being painted.
 *
 * `reply` is what the user typed into the toast, and this is the only route by
 * which it can arrive: an <input>'s text reaches a COM activator and nothing
 * else. Protocol activation, which carries the toast body's own click, cannot. */
static void toast_action_cb(const char *arg, const char *reply) {
    HWND h = FindWindowW(L"OpenChimeWin", NULL);
    if (!h) return;
    char payload[1200];
    snprintf(payload, sizeof payload, "%s\n%s", arg ? arg : "", reply ? reply : "");
    COPYDATASTRUCT cds;
    cds.dwData = OC_COPYDATA_ACTION;
    cds.cbData = (DWORD)(strlen(payload) + 1);
    cds.lpData = payload;
    SendMessageW(h, WM_COPYDATA, 0, (LPARAM)&cds);
}

/* Deliver one notification (REQ-138). ONE call site, three backends, and a
 * FALLBACK CHAIN rather than a single mechanism.
 *
 * The chain is the point. The old code had exactly one surface and returned
 * silently when it was unavailable -- so a Shell_NotifyIcon that failed at
 * logon, which is the common case on a busy shell, dropped every notification
 * for the rest of the session with no setting to reach for and no way to tell.
 * Now: the real toast, else the balloon, else the client's own window. A
 * notification that cannot be delivered at all is a bug, not a state.
 *
 * `g_delivered_by` records which one actually carried it, because "asked for
 * OS" and "got OS" are different facts and the test needs the second. */
static void notify_deliver(const char *title, const char *body, const char *source,
                           uint64_t ws_slot, uint64_t channel_id, int snd) {
    /* `snd` is an SNDV_* index: WHICH system sound this event asks for. Who
     * plays it depends on the backend and is decided below -- Windows for the
     * toast, us for our own window -- so exactly one of them ever does, and the
     * two cannot disagree about which sound it was. */
    g_delivered_by = DELIVERED_NONE;
    if (snd < 0 || snd >= SNDV_COUNT) snd = SNDV_DEFAULT;
    g_last_notify_ws = ws_slot; g_last_notify_cid = channel_id;
    if (g_pref_deliver == DELIVER_NONE) return;
    g_toasts_raised++;


    if (g_pref_deliver == DELIVER_OS) {
        /* Tag and group are per conversation, so a second message REPLACES the
         * first rather than stacking three deep for one busy channel. */
        char tag[64], grp[64], arg[96];
        snprintf(tag, sizeof tag, "c%llu", (unsigned long long)channel_id);
        snprintf(grp, sizeof grp, "w%llu", (unsigned long long)ws_slot);
        /* A REAL openchime:// URL, because the app already speaks them. With
         * activationType="protocol" the click needs no COM activator and no
         * registered CLSID -- Windows just opens the URL, the scheme points at
         * this exe, and the running instance follows it. The conversation, not
         * a line in it: a notification is about the former. */
        snprintf(arg, sizeof arg, "openchime://%s/c/%llu",
                 g_host[0] ? g_host : "workspace", (unsigned long long)channel_id);
        /* Windows plays it, named in the toast. Not us: a sound the OS owns
         * obeys Focus Assist and the per-app notification settings, and one we
         * play behind its back does not. */
        /* Actionable when it names a real conversation: a reply box and the
         * first quick reaction, so the two things you most often want to do
         * about a message can be done without opening the app at all. The test
         * verb's notification names no channel and gets the plain shape. */
        int shown = 0;
        if (g_wintoast_ok && channel_id) {
            char react_arg[160];
            /* A GLYPH, and never NULL. REACT_EMO holds resolved glyphs, but
             * quick_rebuild's fallback path can leave an entry NULL when a
             * configured name is not in the catalogue -- and a name that does
             * not resolve would also render as literal text in the chip the
             * reaction creates. The thumb is spelled out so neither can
             * happen. */
            const char *emo = (g_n_quick > 0 && REACT_EMO[0]) ? REACT_EMO[0]
                                                              : "\xF0\x9F\x91\x8D";
            snprintf(react_arg, sizeof react_arg, "react|%llu|%llu|%s",
                     (unsigned long long)ws_slot, (unsigned long long)channel_id, emo);
            char send_arg[160];
            snprintf(send_arg, sizeof send_arg, "reply|%llu|%llu|",
                     (unsigned long long)ws_slot, (unsigned long long)channel_id);
            const char *labels[2] = { "Send", emo };
            const char *args[2]   = { send_arg, react_arg };
            shown = oc_wintoast_show_actions(title, body, source, tag, grp, arg,
                                             SNDV[snd].winsound, "Reply", labels, args, 2);
        }
        if (!shown && g_wintoast_ok)
            shown = oc_wintoast_show(title, body, tag, grp, arg, SNDV[snd].winsound);
        if (shown) {
            g_delivered_by = DELIVERED_WINRT;
            return;
        }
        /* The balloon has no way to name a sound, so we play it. */
        if (notify_balloon(title, body)) {
            sound_play(snd); g_delivered_by = DELIVERED_BALLOON; return;
        }
    }
    own_toast_show(title, body, ws_slot, channel_id);
    sound_play(snd);                       /* our window, our sound */
    g_delivered_by = DELIVERED_OWN;
}

/* ---- taskbar badge + flash (REQ-138, REQ-286) -----------------------------
 * The taskbar is the notification surface that keeps working when toasts are
 * suppressed — by Focus Assist, by the per-app Windows setting, or by the
 * balloon channel failing — so neither signal here sits behind the toast
 * preference. Two signals: an overlay badge carrying the unread count, and a
 * flash for a message that names you. The badge counts what the sidebar
 * counts — every unread message in every conversation that is not muted; mute
 * is the half of the counting rule REQ-137 already decides, and REQ-284's
 * finer rule (count only what would have notified) is still an open call. */
enum { FLASH_NEVER = 0, FLASH_IDLE = 1, FLASH_ALWAYS = 2 };
static int  g_pref_flash = FLASH_IDLE;
static int  g_flashes_raised;       /* observable by the harness; see test_dump */
static int  g_badge_shown = -1;     /* overlay count last applied; -1 = never */
static ITaskbarList3 *g_taskbar;
static int  g_taskbar_dead;         /* creation failed once; stop retrying */
static UINT g_taskbar_created_msg;  /* "TaskbarButtonCreated" (shell restart) */

/* A 32-bit icon for the overlay: the sidebar badge's notice-coloured disc with
 * the count in white, drawn by hand at SM_CXSMICON. GDI text zeroes the alpha
 * byte of every 32bpp pixel it touches, so the glyphs are rendered first as a
 * grayscale mask (white on black; ANTIALIASED_QUALITY, because ClearType would
 * leave colour fringes in the mask), and disc, text and alpha are then composed
 * per pixel — the disc's coverage from a 4x4 supersample rather than a sqrt,
 * which nothing else in this file needs. */
static HICON badge_icon(int count) {
    int s = GetSystemMetrics(SM_CXSMICON);
    if (s < 16) s = 16;
    BITMAPINFO bi;
    ZeroMemory(&bi, sizeof bi);
    bi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bi.bmiHeader.biWidth = s; bi.bmiHeader.biHeight = -s;   /* top-down */
    bi.bmiHeader.biPlanes = 1; bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;
    HDC mem = CreateCompatibleDC(NULL);
    void *bits = NULL;
    HBITMAP dib = mem ? CreateDIBSection(mem, &bi, DIB_RGB_COLORS, &bits, NULL, 0) : NULL;
    if (!dib || !bits) {
        if (dib) DeleteObject(dib);
        if (mem) DeleteDC(mem);
        return NULL;
    }
    HGDIOBJ oldbm = SelectObject(mem, dib);
    char t[4];
    if (count > 9) snprintf(t, sizeof t, "9+");
    else           snprintf(t, sizeof t, "%d", count);
    WCHAR wt[4];
    to_w(t, wt, 4);
    HFONT font = CreateFontW(-(s * (count > 9 ? 10 : 12) / 16), 0, 0, 0, FW_BOLD,
                             0, 0, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS,
                             CLIP_DEFAULT_PRECIS, ANTIALIASED_QUALITY,
                             DEFAULT_PITCH | FF_DONTCARE, L"Segoe UI");
    HGDIOBJ oldf = SelectObject(mem, font);
    SetTextColor(mem, RGB(255, 255, 255));
    SetBkMode(mem, TRANSPARENT);
    RECT tr = { 0, 0, s, s };
    DrawTextW(mem, wt, -1, &tr, DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
    GdiFlush();
    uint32_t disc = OC_COL_NOTICE;
    unsigned dr = (disc >> 16) & 0xFF, dg = (disc >> 8) & 0xFF, db = disc & 0xFF;
    uint32_t *px = (uint32_t *)bits;
    for (int y = 0; y < s; y++) {
        for (int x = 0; x < s; x++) {
            /* Subsample centres in 1/8-pixel units: pixel x covers
             * [8x, 8x+8), samples at 8x + 2k + 1; the disc's centre is 4s and
             * its radius (4s - 2), a quarter pixel in from the icon edge. */
            int hits = 0;
            for (int sy = 0; sy < 4; sy++)
                for (int sx = 0; sx < 4; sx++) {
                    int ddx = 8 * x + 2 * sx + 1 - 4 * s;
                    int ddy = 8 * y + 2 * sy + 1 - 4 * s;
                    if (ddx * ddx + ddy * ddy <= (4 * s - 2) * (4 * s - 2)) hits++;
                }
            unsigned a  = (unsigned)(hits * 255 / 16);
            unsigned tc = (px[y * s + x] >> 8) & 0xFF;      /* text coverage */
            unsigned r8 = (dr * (255 - tc) + 255 * tc) / 255;
            unsigned g8 = (dg * (255 - tc) + 255 * tc) / 255;
            unsigned b8 = (db * (255 - tc) + 255 * tc) / 255;
            px[y * s + x] = (a << 24) | (r8 << 16) | (g8 << 8) | b8;
        }
    }
    SelectObject(mem, oldf);
    DeleteObject(font);
    SelectObject(mem, oldbm);
    /* ICONINFO requires a mask even though the 32bpp alpha supersedes it; a
     * zeroed one, because CreateBitmap with no bits is uninitialised memory. */
    int mrow = ((s + 15) / 16) * 2;
    uint8_t *mb = calloc((size_t)mrow * s, 1);
    HBITMAP mask = mb ? CreateBitmap(s, s, 1, 1, mb) : NULL;
    free(mb);
    ICONINFO ii = { TRUE, 0, 0, mask, dib };
    HICON ic = mask ? CreateIconIndirect(&ii) : NULL;
    if (mask) DeleteObject(mask);
    DeleteObject(dib);
    DeleteDC(mem);
    return ic;
}

/* Apply `count` to the taskbar button (0 clears; anything past 9 renders as
 * "9+"), creating the ITaskbarList3 on first use — COM is already initialised
 * for WIC. The description string carries the number for a screen reader,
 * since the overlay's pixels cannot. */
static HRESULT g_taskbar_hr;    /* the failing step's answer; see test_dump */
static void taskbar_badge_apply(HWND hwnd, int count) {
    /* A failed apply is retried, but not at tick rate: the caller re-enters
     * every ~30ms while the count disagrees with what was applied, and
     * rebuilding a DIB, a font and an icon 33 times a second is the wrong
     * response to the low-GDI condition that most likely caused the miss. */
    static ULONGLONG backoff;
    if (backoff && GetTickCount64() < backoff) return;
    backoff = 0;
    if (g_taskbar_dead) return;
    if (!g_taskbar) {
        g_taskbar_hr = CoCreateInstance(&OC_CLSID_TaskbarList, NULL, CLSCTX_INPROC_SERVER,
                                        &OC_IID_ITaskbarList3, (void **)&g_taskbar);
        if (SUCCEEDED(g_taskbar_hr) && g_taskbar)
            g_taskbar_hr = ITaskbarList3_HrInit(g_taskbar);
        if (FAILED(g_taskbar_hr) || !g_taskbar) {
            if (g_taskbar) { ITaskbarList3_Release(g_taskbar); g_taskbar = NULL; }
            g_taskbar_dead = 1;         /* no ITaskbarList3: live without a badge */
            return;
        }
    }
    HICON ic = NULL;
    WCHAR alt[24] = L"";
    if (count > 0) {
        ic = badge_icon(count);
        if (!ic) { backoff = GetTickCount64() + 1000; return; }
        char a[24];
        if (count > 9) snprintf(a, sizeof a, "9+ unread");
        else           snprintf(a, sizeof a, "%d unread", count);
        to_w(a, alt, 24);
    }
    if (SUCCEEDED(ITaskbarList3_SetOverlayIcon(g_taskbar, hwnd, ic,
                                               count > 0 ? alt : NULL)))
        g_badge_shown = count;
    else
        backoff = GetTickCount64() + 1000;
    if (ic) DestroyIcon(ic);
}

/* Flash the taskbar button for a message that NAMES you (REQ-286), until the
 * window comes forward. "When idle" is the split the always case forces —
 * essential when you have stepped away, intrusive when you are typing in the
 * next window — read as no keyboard or mouse input for thirty seconds. */
static void taskbar_flash(HWND hwnd) {
    if (g_pref_flash == FLASH_NEVER) return;
    if (g_pref_flash == FLASH_IDLE) {
        LASTINPUTINFO li = { sizeof li, 0 };
        if (GetLastInputInfo(&li) && GetTickCount() - li.dwTime < 30000) return;
    }
    FLASHWINFO fi = { sizeof fi, hwnd, FLASHW_TRAY | FLASHW_TIMERNOFG, 0, 0 };
    FlashWindowEx(&fi);
    g_flashes_raised++;
}

/* ---- inline image thumbnails -------------------------------------
 * Attachments rendered as text lines only. The bytes are fetched INTO MEMORY
 * (oc_client_fetch_attachment) and decoded with WIC — no temp file, because a
 * client stores nothing locally (ARCH-88) and a scratch file for rendering is
 * exactly the cache that decision removed.
 *
 * The decoded bitmaps belong to the render target, so the cache is dropped
 * whenever the RT is recreated. */
#define THUMB_H UIS(160.0f)
#define THUMB_W UIS(260.0f)
enum { THUMB_CACHE = 32 };
/* Dimensions are captured at decode time from WIC with explicit out-params
 * (the by-value GetSize ABI hazard is recorded in git history). `px` is the
 * decoded PBGRA image, kept alongside the texture so it can be re-uploaded if
 * the renderer's device resets — same shape the D2D cache had, one target
 * dance lighter: an SDL texture draws into every render pass, screenshots
 * included, so the per-shot bitmap machinery is gone. */
static struct { uint64_t id; gfx_tex *tex; UINT w, h; uint8_t *px; UINT stride; } g_thumbs[THUMB_CACHE];
static int      g_n_thumbs;
static int g_thumbs_off;                        /* a capture suppresses FETCHES only */
static uint64_t g_thumb_missing[THUMB_CACHE];   /* asked for, nothing came back */
static int      g_n_thumb_missing;
static uint64_t g_thumb_pending;                /* one fetch in flight */
/* Click-to-expand: the thumbnails on screen, and the one being viewed full
 * size. The bitmap is already decoded at native resolution — the transcript
 * merely draws it small — so expanding costs nothing but a bigger destination
 * rect. */
static struct { rectf r; uint64_t id; } g_thumb_hits[32];
static int      g_n_thumb_hits;
/* Forward quote cards (REQ-057): clicking one goes to the original, which is
 * the whole point of a reference — the card names the source's files, and this
 * is how a reader reaches them without a download button that would fail for
 * anyone who cannot read that channel. */
static struct { rectf r; uint64_t chan, mid; } g_fwd_hits[32];
static int      g_n_fwd_hits;
static uint64_t g_lightbox;
/* Slack's pattern: the image itself is the click target for a bigger view, and
 * saving it is a button that appears on hover — so the affordance is there when
 * you look for it and out of the way when you are reading. */
static uint64_t g_thumb_hover;
static struct { rectf r; int attach_ix; uint64_t mid; } g_thumb_dl[32];
static int      g_n_thumb_dl;
static ULONGLONG g_thumb_deadline;
static IWICImagingFactory *g_wic;

/* Only what WIC will actually decode, and only from the server's declared mime —
 * guessing from the filename would mean fetching whatever someone chose to call
 * a .png. */
static int mime_is_image(const char *mime) {
    return mime && (strcmp(mime, "image/png") == 0 || strcmp(mime, "image/jpeg") == 0 ||
                    strcmp(mime, "image/gif") == 0 || strcmp(mime, "image/bmp") == 0 ||
                    strcmp(mime, "image/webp") == 0);
}

static gfx_tex *thumb_get(gfx *rt, uint64_t id, UINT *w, UINT *h) {
    (void)rt;
    for (int i = 0; i < g_n_thumbs; i++) {
        if (g_thumbs[i].id != id) continue;
        if (w) *w = g_thumbs[i].w;
        if (h) *h = g_thumbs[i].h;
        /* Device reset dropped the texture: re-upload from the kept pixels. */
        if (!g_thumbs[i].tex && g_thumbs[i].px)
            g_thumbs[i].tex = gfx_tex_create_text(g_gfx, g_thumbs[i].px,
                                                  (int)g_thumbs[i].stride,
                                                  (int)g_thumbs[i].w,
                                                  (int)g_thumbs[i].h);
        return g_thumbs[i].tex;
    }
    return NULL;
}

static int thumb_failed(uint64_t id) {
    for (int i = 0; i < g_n_thumb_missing; i++) if (g_thumb_missing[i] == id) return 1;
    return 0;
}
static void thumbs_drop(void) {
    for (int i = 0; i < g_n_thumbs; i++) {
        if (g_thumbs[i].tex) gfx_tex_destroy(g_thumbs[i].tex);
        free(g_thumbs[i].px);
        g_thumbs[i].px = NULL;
    }
    g_n_thumbs = 0;
}

/* A user's avatar id, or 0. Roster-carried, so no round trip per author. */
static uint64_t avatar_of(const oc_model *m, uint64_t uid) {
    if (!m || !uid) return 0;
    for (size_t i = 0; i < m->n_users; i++)
        if (m->users[i].user_id == uid) return m->users[i].avatar_id;
    return 0;
}

/* Draw a user's avatar in `box`: their photo when we have the bytes, the coloured
 * initial otherwise.
 *
 * The image is CIRCLE-CLIPPED by filling an ellipse with a bitmap brush rather than
 * pushing a layer: a layer costs a render-target flush per avatar, and a transcript
 * can hold dozens. The brush transform scales the shorter edge to the box and
 * centres the overflow, so a non-square photo is cropped rather than squashed.
 *
 * It shares the thumbnail cache and its single-fetch-in-flight rule, so avatars and
 * inline images cannot fight each other for the one transfer slot.
 * `square` draws a rounded square instead (the sidebar's DM rows and the rail). */
static gfx_tex *thumb_get(gfx *rt, uint64_t id, UINT *w, UINT *h);  /* fwd */
static int thumb_failed(uint64_t id);                                                  /* fwd */

static int draw_avatar_image(gfx *rt, uint64_t aid, rectf box,
                             float radius, int square) {
    UINT iw = 0, ih = 0;
    gfx_tex *bmp = aid ? thumb_get(rt, aid, &iw, &ih) : NULL;
    if (!bmp || !iw || !ih) return 0;
    float bw = box.right - box.left, bh = box.bottom - box.top;
    /* Cover-fit: the SHAPE is the box (a disc, or a rounded square) drawn
     * exactly; the image is sampled as if it filled the enlarged, centered
     * rect, so a non-square photo is cropped rather than squashed — the same
     * geometry the old bitmap-brush transform produced. */
    float scale = (iw * bh > ih * bw) ? (bh / (float)ih) : (bw / (float)iw);
    float dw = iw * scale, dh = ih * scale;
    gfx_rect map = { box.left + (bw - dw) / 2, box.top + (bh - dh) / 2, dw, dh };
    gfx_tex_draw_shaped(rt, bmp, gr(box), square ? radius : bw / 2.0f, map, 1.0f);
    return 1;
}

